from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
checks=[]
def has(rel,*parts):
    s=(ROOT/rel).read_text(encoding='utf-8')
    return all(p in s for p in parts)
def check(name,ok):
    checks.append(bool(ok)); print(('PASS' if ok else 'FAIL')+' - '+name)
check('canonical directionality enum exists', has('src/main/java/com/example/editor/transformation/core/TransformationDirectionality.java','UNIDIRECTIONAL','BIDIRECTIONAL'))
check('rule direction is explicit', has('src/main/java/com/example/editor/transformation/core/TransformationRule.java','TransformationRuleDirection direction','String correspondenceId'))
check('definition persists directionality and synchronization policy', has('src/main/java/com/example/editor/transformation/core/TransformationDefinitionDocument.java','TransformationDirectionality directionality','TransformationSynchronizationPolicy synchronizationPolicy','CURRENT_SCHEMA_VERSION = "1.1"'))
check('legacy definition constructor remains forward-compatible', has('src/main/java/com/example/editor/transformation/core/TransformationDefinitionDocument.java','TransformationDirectionality.UNIDIRECTIONAL','Backward-compatible'))
check('bidirectional mode is M2M only', has('src/main/java/com/example/editor/transformation/TransformationDefinitionChecker.java','BIDIRECTIONAL_ONLY_M2M'))
check('bidirectional execution requires trace', has('src/main/java/com/example/editor/transformation/TransformationDefinitionChecker.java','BIDIRECTIONAL_TRACE_REQUIRED'))
check('checker requires an explicit bidirectional rule pair', has('src/main/java/com/example/editor/transformation/TransformationDefinitionChecker.java','BIDIRECTIONAL_RULE_PAIR_REQUIRED','INCOMPLETE_BIDIRECTIONAL_CORRESPONDENCE'))
check('checker requires stable paired correspondence', has('src/main/java/com/example/editor/transformation/TransformationDefinitionChecker.java','CORRESPONDENCE_ID_REQUIRED','INCOMPLETE_BIDIRECTIONAL_CORRESPONDENCE') and has('src/main/java/com/example/editor/transformation/TransformationDefinitionChecker.java','HYDRA will not guess inverse bindings'))
check('reverse rules are rejected in unidirectional mode', has('src/main/java/com/example/editor/transformation/TransformationDefinitionChecker.java','REVERSE_RULE_REQUIRES_BIDIRECTIONAL'))
check('compiler selects rules by execution direction', has('src/main/java/com/example/editor/transformation/runtime/TransformationPlanCompiler.java','TransformationRuleDirection.REVERSE','rule.direction() == ruleDirection'))
check('compiler swaps semantic endpoints for reverse', has('src/main/java/com/example/editor/transformation/runtime/TransformationPlanCompiler.java','document.targets().getFirst() : document.sources().getFirst()','document.sources().getFirst() : document.targets().getFirst()'))
check('runtime can execute explicit reverse direction', has('src/main/java/com/example/editor/transformation/runtime/TransformationRuntimeService.java','TransformationExecutionDirection direction','effective == TransformationExecutionDirection.REVERSE'))
check('trace records correspondence and direction', has('src/main/java/com/example/editor/transformation/runtime/TransformationTraceLink.java','String correspondenceId','TransformationExecutionDirection direction'))
check('trace root records execution direction', has('src/main/java/com/example/editor/transformation/runtime/TransformationTrace.java','TransformationExecutionDirection direction'))
check('runtime creates direction-aware deterministic ids', has('src/main/java/com/example/editor/transformation/runtime/CanonicalTransformationRuntime.java','plan.direction() + "|" + sourceModel.id()'))
check('batch synchronization exists', has('src/main/java/com/example/editor/transformation/runtime/TransformationRuntimeService.java','synchronizeDraft','TransformationSynchronizationSide.SOURCE','TransformationSynchronizationSide.TARGET'))
check('both-side conflicts fail closed by default', has('src/main/java/com/example/editor/transformation/runtime/TransformationRuntimeService.java','FAIL_ON_CONFLICT','Both sides changed'))
check('conflict winner selects deterministic direction', has('src/main/java/com/example/editor/transformation/runtime/TransformationRuntimeService.java','FORWARD_WINS','TransformationExecutionDirection.REVERSE'))
check('controller exposes directional execute', has('src/main/java/com/example/editor/transformation/web/TransformationController.java','/{id}/execute/{direction}'))
check('controller exposes synchronization preview and persisted operation', has('src/main/java/com/example/editor/transformation/web/TransformationController.java','/preview-synchronize','/{id}/synchronize'))
check('export accepts explicit direction', has('src/main/java/com/example/editor/transformation/export/TransformationExportRequest.java','TransformationExecutionDirection direction'))
check('export uses directional projection instead of guessing inverse', has('src/main/java/com/example/editor/transformation/export/TransformationDirectionalExportView.java','rule.direction() == expected','asForwardRule'))
check('manual parity carries execution direction', has('src/main/java/com/example/editor/transformation/parity/TransformationParityRequest.java','TransformationExecutionDirection direction'))
check('native full synchronization remains distinct from directional branch parity', has('src/main/java/com/example/editor/transformation/nativeexec/TransformationNativeRuntimeSupport.java','supportsFullBidirectionalSynchronization','false, false') and has('src/main/java/com/example/editor/transformation/nativeexec/TransformationNativeParityService.java','TransformationExecutionDirection.REVERSE','supportsDirection'))
check('frontend exposes unidirectional and bidirectional choice', has('frontend/src/transformation-designer/TransformationDesigner.tsx','Unidirectional','Bidirectional'))
check('frontend maps forward and backward rules', has('frontend/src/transformation-designer/TransformationMappingWorkspace.tsx','Rule direction','Create backward rule'))
check('frontend previews either execution direction', has('frontend/src/transformation-designer/TransformationPreviewPanel.tsx','Execution direction','previewTransformation(document,model,executionDirection)'))
check('frontend exposes batch synchronization', has('frontend/src/transformation-designer/TransformationPreviewPanel.tsx','Bidirectional synchronization','runSynchronization'))
check('frontend export chooses direction', has('frontend/src/transformation-designer/TransformationExportPanel.tsx','Export direction','exportTransformation(document,language,direction)'))
check('test cases persist direction', has('src/main/java/com/example/editor/transformation/testing/TransformationTestCase.java','TransformationExecutionDirection executionDirection'))
check('OpenAPI includes new directional/sync endpoints', has('docs/api/hydra-openapi.yaml','/api/transformations/preview-synchronize:','/api/transformations/{id}/execute/{direction}:','/api/transformations/{id}/synchronize:'))
passed=sum(checks); print(f'FIX38_BIDIRECTIONAL_TRANSFORMATIONS={passed}/{len(checks)}')
raise SystemExit(0 if passed==len(checks) else 1)
